(function () {
  /**
   * Minimal fetch-based client for Power Automate HTTP-trigger flows.
   * If you already have a richer client, replace this file while keeping the same API:
   *   window.PowerAutomateClient.request(url, payload) -> Promise<{ok:boolean, data:any, error?:string}>
   */
  async function request(url, payload) {
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const text = await res.text();
      let data;
      try { data = JSON.parse(text); } catch { data = text; }
      if (!res.ok) return { ok: false, error: `HTTP ${res.status}`, data };
      return { ok: true, data };
    } catch (e) {
      return { ok: false, error: String(e), data: null };
    }
  }
  window.PowerAutomateClient = { request };
})();

import { startRouter } from "./core/router.js";
import { registerBindings } from "./events/bindings.js";
import { renderApp } from "./views/layout.js";
import { initBootstrap } from "./services/bootstrap.js";
import { listInbox } from "./services/inbox.js";
import { listInward, listOutward } from "./services/correspondence.js";
import { listApprovals } from "./services/approvals.js";
import { listTasks } from "./services/tasks.js";
import { listNotifications, listAudit, listDirectory } from "./services/ops.js";
import { listMeetings } from "./services/meetings.js";
import { listBriefs } from "./services/briefs.js";
import { listDecisions } from "./services/decisions.js";

registerBindings();
startRouter();

await initBootstrap();

// Prime key queues in parallel (best-effort; demo/bootstrap may already fill them)
Promise.allSettled([
  listInbox(),
  listInward(),
  listOutward(),
  listApprovals(),
  listTasks(),
  listMeetings(),
  listBriefs(),
  listDecisions(),
  listNotifications(),
  listAudit(),
  listDirectory()
]).finally(() => renderApp());

import { Store, setDeepValue, closeModal } from "../core/store.js";
import { debounce } from "../utils/fn.js";
import { dispatchAction } from "../controllers/actions.js";
import { renderApp } from "../views/layout.js";

export function registerBindings() {
  // Generic data-bind (input/select/textarea)
  document.addEventListener("input", (e) => {
    const el = e.target;
    const bind = el?.dataset?.bind;
    if (!bind) return;
    setDeepValue(Store, bind, el.value);
  });

  // Enter to close modal (Esc)
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && Store.ui.modal) {
      closeModal();
      renderApp();
    }
  });

  // Click actions
  document.addEventListener("click", async (e) => {
    const el = e.target?.closest?.("[data-action]");
    if (!el) return;
    e.preventDefault();
    await dispatchAction(el.dataset.action, el);
  });

  // (Reserved) Debounced search hooks
  document.addEventListener("keyup", debounce(() => {}, 250));
}

