export function setDeepValue(obj, path, value) {
  const parts = String(path).split(".");
  let ref = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    const k = parts[i];
    if (!(k in ref) || ref[k] === null) ref[k] = {};
    ref = ref[k];
  }
  ref[parts[parts.length - 1]] = value;
}

