        </div>
        <div class="mt-2 text-xs text-slate-500">Please wait.</div>
      </div>
    </div>` : "";

  const modal = Store.ui.modal ? Store.ui.modal : "";

  app.innerHTML = `
    <div class="min-h-screen flex">
      ${renderSidebar()}
      ${overlay}
      <main class="flex-1 min-w-0">
        ${renderHeader()}
        <div class="px-4 md:px-6 py-6">
          ${renderRoute()}
        </div>
      </main>
    </div>
    ${toast}
    ${busy}
    ${modal}
  `;

  // icons
  window.lucide?.createIcons?.();
}

